1	//! The `.fjgraphic` package (spec §11 G-46 (c)): the package spec's parse and
2	//! checks, the in-package name legaliser, `manifest.json`, the stored zip
3	//! with its CRC-32, and the file write. The app hands in the module's and
4	//! the files' bytes and their project-relative paths; which fonts and assets
5	//! belong in a package is decided before this module is reached.
6	//!
7	//! **The archive** is a stored zip (method 0), version needed 10, made-by
8	//! `0x031E`, flag bit 11 (UTF-8 names), DOS time 0 and date `0x0021`
9	//! (1980-01-01) so two writes of one package are byte-identical, no extra
10	//! fields and no directory entries, external attributes `0o100644 << 16`:
11	//! `manifest.json` first, then the files in the order given, then the central
12	//! directory and the end record. There is no Zip64, so an archive over
13	//! `u32::MAX` bytes (or of more than 65,535 entries) is refused.
14	//!
15	//! **An in-package name** `<n>` under `fonts/` or `assets/` is legal when it
16	//! is non-empty, at most 255 bytes, does not begin with `.`, and holds no
17	//! `/`, `\`, `:` or control scalar (U+0000–U+001F, U+007F–U+009F). Per
18	//! folder, the legal names are claimed first in the order given; then each
19	//! illegal one, in order, has each run of `\`, `:` or control scalars made
20	//! one `-` and its leading `.`s dropped (empty is `file`), and a name already
21	//! claimed takes `-2`, `-3`, … before its last `.` (G-23 (c)'s form), the
22	//! stem cut by whole scalars to stay within 255 bytes. The manifest's `name`
23	//! keeps the project's own name.
24	
25	use std::collections::HashSet;
26	
27	use serde_json::{json, Map, Value};
28	use sha2::{Digest, Sha256};
29	
30	use crate::model_graphic::check_name;
31	
32	/// The longest in-package name, in UTF-8 bytes (APFS's file-name limit).
33	const MAX_NAME: usize = 255;
34	const MANIFEST: &str = "manifest.json";
35	/// A local header's fixed part, and a central directory entry's.
36	const LOCAL_FIXED: usize = 30;
37	const CENTRAL_FIXED: usize = 46;
38	const END_RECORD: usize = 22;
39	/// 1980-01-01 as a DOS date: day 1, month 1, year 0.
40	const DOS_DATE: u16 = 0x0021;
41	/// Bit 11: the names are UTF-8.
42	const UTF8_FLAG: u16 = 0x0800;
43	/// Unix (3) and spec version 3.0 (30), the high and low bytes.
44	const MADE_BY: u16 = 0x031E;
45	/// A regular file, `rw-r--r--`, in the external attributes' high half.
46	const EXTERNAL: u32 = 0o100644 << 16;
47	
48	/// One file of the package: its in-package path, its project-folder name, its bytes.
49	struct Entry<'a> {
50	    path: String,
51	    name: String,
52	    bytes: &'a [u8],
53	}
54	
55	/// Checks `package_json` against `data`, writes the archive at `path`
56	/// (created or truncated) and answers the `manifest.json` it holds. Every
57	/// refusal names the value; an input refusal writes nothing.
58	pub(crate) fn write(path: &str, package_json: &str, data: &[u8]) -> Result<String, String> {
59	    let archive = build(package_json, data)?;
60	    std::fs::write(path, &archive.1).map_err(|e| format!("cannot write {path}: {e}"))?;
61	    Ok(archive.0)
62	}
63	
64	/// The manifest's text and the archive's bytes.
65	fn build(package_json: &str, data: &[u8]) -> Result<(String, Vec<u8>), String> {
66	    let spec: Value =
67	        serde_json::from_str(package_json).map_err(|e| format!("package_json is not JSON: {e}"))?;
68	    let Some(spec) = spec.as_object() else {
69	        return Err(format!("package_json must be an object, not {spec}"));
70	    };
71	    let module = match spec.get("module") {
72	        Some(Value::String(module)) => module.clone(),
73	        other => return Err(format!("module must be a string, not {}", shown(other))),
74	    };
75	    check_name(&module)?;
76	    let title = string(spec, "title")?;
77	    let category = string(spec, "category")?;
78	    let app_version = string(spec, "app_version")?;
79	    let description = match spec.get("description") {
80	        Some(Value::String(text)) => Value::String(text.clone()),
81	        Some(Value::Null) => Value::Null,
82	        other => {
83	            return Err(format!(
84	                "description must be a string or null, not {}",
85	                shown(other)
86	            ))
87	        }
88	    };
89	    let files = parse_files(spec, &module)?;
90	    let total = files
91	        .iter()
92	        .try_fold(0u64, |sum, (_, size)| sum.checked_add(*size))
93	        .ok_or_else(|| "the files' sizes overflow".to_string())?;
94	    if total != data.len() as u64 {
95	        return Err(format!(
96	            "the files' sizes sum to {total} bytes, but data holds {}",
97	            data.len()
98	        ));
99	    }
100	    let names = package_names(&files);
101	    let mut entries = Vec::with_capacity(files.len());
102	    let mut at = 0usize;
103	    for ((given, size), path) in files.iter().zip(names) {
104	        let end = at + *size as usize;
105	        let name = given.rsplit('/').next().unwrap_or(given).to_string();
106	        entries.push(Entry {
107	            path,
108	            name,
109	            bytes: &data[at..end],
110	        });
111	        at = end;
112	    }
113	    let listed: Vec<Value> = entries
114	        .iter()
115	        .map(|entry| {
116	            json!({
117	                "path": entry.path,
118	                "name": entry.name,
119	                "size": entry.bytes.len(),
120	                "sha256": hex(&Sha256::digest(entry.bytes)),
121	            })
122	        })
123	        .collect();
124	    let mut manifest = Map::new();
125	    manifest.insert("fjgraphic".to_string(), Value::from(1));
126	    manifest.insert("module".to_string(), Value::String(module));
127	    manifest.insert("title".to_string(), Value::String(title));
128	    manifest.insert("category".to_string(), Value::String(category));
129	    manifest.insert("description".to_string(), description);
130	    manifest.insert("app_version".to_string(), Value::String(app_version));
131	    manifest.insert("files".to_string(), Value::Array(listed));
132	    let mut text = serde_json::to_string_pretty(&Value::Object(manifest))
133	        .map_err(|e| format!("the manifest could not be written: {e}"))?;
134	    text.push('\n');
135	    let mut all = vec![(MANIFEST.to_string(), text.as_bytes())];
136	    all.extend(entries.iter().map(|e| (e.path.clone(), e.bytes)));
137	    let archive = zip(&all)?;
138	    Ok((text, archive))
139	}
140	
141	/// A value as a refusal names it; a missing key is `nothing`.
142	fn shown(value: Option<&Value>) -> String {
143	    value.map_or_else(|| "nothing".to_string(), Value::to_string)
144	}
145	
146	fn string(spec: &Map<String, Value>, key: &str) -> Result<String, String> {
147	    match spec.get(key) {
148	        Some(Value::String(text)) => Ok(text.clone()),
149	        other => Err(format!("{key} must be a string, not {}", shown(other))),
150	    }
151	}
152	
153	/// `files` as `(path, size)` pairs: the first exactly `<module>.js`, every
154	/// other `fonts/<n>` or `assets/<n>`, no path twice.
155	fn parse_files(spec: &Map<String, Value>, module: &str) -> Result<Vec<(String, u64)>, String> {
156	    let Some(Value::Array(list)) = spec.get("files") else {
157	        return Err(format!(
158	            "files must be an array, not {}",
159	            shown(spec.get("files"))
160	        ));
161	    };
162	    let mut files = Vec::with_capacity(list.len());
163	    let mut seen = HashSet::new();
164	    for (index, file) in list.iter().enumerate() {
165	        let path = match file.get("path") {
166	            Some(Value::String(path)) => path.clone(),
167	            other => {
168	                return Err(format!(
169	                    "files[{index}].path must be a string, not {}",
170	                    shown(other)
171	                ))
172	            }
173	        };
174	        let Some(size) = file.get("size").and_then(Value::as_u64) else {
175	            return Err(format!(
176	                "files[{index}].size must be a whole number of bytes, not {}",
177	                shown(file.get("size"))
178	            ));
179	        };
180	        let module_file = format!("{module}.js");
181	        if index == 0 {
182	            if path != module_file {
183	                return Err(format!(
184	                    "the first file must be \"{module_file}\", not \"{path}\""
185	                ));
186	            }
187	        } else if !in_folder(&path) {
188	            return Err(format!(
189	                "file \"{path}\" is not fonts/<name> or assets/<name> (a name of 1 to 255 bytes with no /)"
190	            ));
191	        }
192	        if !seen.insert(path.clone()) {
193	            return Err(format!("file \"{path}\" is given twice"));
194	        }
195	        files.push((path, size));
196	    }
197	    if files.is_empty() {
198	        return Err(format!(
199	            "files must begin with \"{module}.js\", not be empty"
200	        ));
201	    }
202	    Ok(files)
203	}
204	
205	/// `fonts/<n>` or `assets/<n>`, `<n>` non-empty, at most 255 bytes, no `/`.
206	fn in_folder(path: &str) -> bool {
207	    let name = path
208	        .strip_prefix("fonts/")
209	        .or_else(|| path.strip_prefix("assets/"));
210	    name.is_some_and(|n| !n.is_empty() && n.len() <= MAX_NAME && !n.contains('/'))
211	}
212	
213	/// U+0000–U+001F and U+007F–U+009F.
214	fn is_control(c: char) -> bool {
215	    matches!(c as u32, 0..=0x1F | 0x7F..=0x9F)
216	}
217	
218	/// What the legaliser replaces: `\`, `:` and the control scalars.
219	fn is_replaced(c: char) -> bool {
220	    c == '\\' || c == ':' || is_control(c)
221	}
222	
223	fn is_legal(name: &str) -> bool {
224	    !name.is_empty()
225	        && name.len() <= MAX_NAME
226	        && !name.starts_with('.')
227	        && !name.chars().any(|c| c == '/' || is_replaced(c))
228	}
229	
230	/// Each run of replaced scalars one `-`, leading `.`s dropped, empty `file`.
231	fn legalise(name: &str) -> String {
232	    let mut out = String::with_capacity(name.len());
233	    let mut in_run = false;
234	    for c in name.chars() {
235	        if is_replaced(c) {
236	            if !in_run {
237	                out.push('-');
238	            }
239	            in_run = true;
240	        } else {
241	            out.push(c);
242	            in_run = false;
243	        }
244	    }
245	    let kept = out.trim_start_matches('.');
246	    if kept.is_empty() {
247	        "file".to_string()
248	    } else {
249	        kept.to_string()
250	    }
251	}
252	
253	/// `name` with `-<k>` before its last `.`, the stem (then, only if it must,
254	/// the extension) cut by whole scalars to stay within 255 bytes.
255	fn suffixed(name: &str, k: usize) -> String {
256	    let (mut stem, mut ext) = match name.rfind('.') {
257	        Some(dot) if dot > 0 => (name[..dot].to_string(), name[dot..].to_string()),
258	        _ => (name.to_string(), String::new()),
259	    };
260	    let tag = format!("-{k}");
261	    while stem.len() + tag.len() + ext.len() > MAX_NAME {
262	        if stem.pop().is_none() && ext.pop().is_none() {
263	            break;
264	        }
265	    }
266	    format!("{stem}{tag}{ext}")
267	}
268	
269	/// Each file's in-package path: the module's as given; per folder, the legal
270	/// names claimed first, then each illegal one legalised and suffixed free.
271	fn package_names(files: &[(String, u64)]) -> Vec<String> {
272	    let mut out: Vec<Option<String>> = vec![None; files.len()];
273	    out[0] = Some(files[0].0.clone());
274	    for folder in ["fonts/", "assets/"] {
275	        let mine: Vec<(usize, &str)> = files
276	            .iter()
277	            .enumerate()
278	            .skip(1)
279	            .filter_map(|(i, (path, _))| path.strip_prefix(folder).map(|n| (i, n)))
280	            .collect();
281	        let mut claimed: HashSet<String> = HashSet::new();
282	        for &(i, name) in &mine {
283	            if is_legal(name) {
284	                claimed.insert(name.to_string());
285	                out[i] = Some(format!("{folder}{name}"));
286	            }
287	        }
288	        for &(i, name) in &mine {
289	            if is_legal(name) {
290	                continue;
291	            }
292	            let base = legalise(name);
293	            let mut chosen = base.clone();
294	            let mut k = 2;
295	            while claimed.contains(&chosen) {
296	                chosen = suffixed(&base, k);
297	                k += 1;
298	            }
299	            claimed.insert(chosen.clone());
300	            out[i] = Some(format!("{folder}{chosen}"));
301	        }
302	    }
303	    out.into_iter().map(Option::unwrap_or_default).collect()
304	}
305	
306	fn hex(bytes: &[u8]) -> String {
307	    bytes.iter().map(|b| format!("{b:02x}")).collect()
308	}
309	
310	/// CRC-32 (IEEE): the reflected polynomial `0xEDB88320`, init and xorout
311	/// `0xFFFFFFFF`, by a 256-entry table.
312	fn crc32(bytes: &[u8]) -> u32 {
313	    let mut table = [0u32; 256];
314	    for (n, slot) in table.iter_mut().enumerate() {
315	        let mut c = n as u32;
316	        for _ in 0..8 {
317	            c = if c & 1 != 0 {
318	                0xEDB8_8320 ^ (c >> 1)
319	            } else {
320	                c >> 1
321	            };
322	        }
323	        *slot = c;
324	    }
325	    let mut crc = 0xFFFF_FFFFu32;
326	    for &b in bytes {
327	        crc = table[((crc ^ u32::from(b)) & 0xFF) as usize] ^ (crc >> 8);
328	    }
329	    crc ^ 0xFFFF_FFFF
330	}
331	
332	/// The stored zip of `entries`, in order; refused past what a zip without
333	/// Zip64 can hold.
334	fn zip(entries: &[(String, &[u8])]) -> Result<Vec<u8>, String> {
335	    let mut size: u64 = END_RECORD as u64;
336	    for (name, bytes) in entries {
337	        size += (LOCAL_FIXED + CENTRAL_FIXED + 2 * name.len() + bytes.len()) as u64;
338	    }
339	    if size > u64::from(u32::MAX) || entries.len() > usize::from(u16::MAX) {
340	        return Err(format!(
341	            "the package would be {size} bytes in {} entries, more than a zip without Zip64 holds ({} bytes, {} entries)",
342	            entries.len(),
343	            u32::MAX,
344	            u16::MAX
345	        ));
346	    }
347	    let mut out = Vec::with_capacity(size as usize);
348	    let mut central = Vec::new();
349	    for (name, bytes) in entries {
350	        let offset = out.len() as u32;
351	        let crc = crc32(bytes);
352	        let len = bytes.len() as u32;
353	        let name_len = name.len() as u16;
354	        put32(&mut out, 0x0403_4b50);
355	        for field in [10, UTF8_FLAG, 0, 0, DOS_DATE] {
356	            put16(&mut out, field);
357	        }
358	        for field in [crc, len, len] {
359	            put32(&mut out, field);
360	        }
361	        put16(&mut out, name_len);
362	        put16(&mut out, 0);
363	        out.extend_from_slice(name.as_bytes());
364	        out.extend_from_slice(bytes);
365	
366	        put32(&mut central, 0x0201_4b50);
367	        for field in [MADE_BY, 10, UTF8_FLAG, 0, 0, DOS_DATE] {
368	            put16(&mut central, field);
369	        }
370	        for field in [crc, len, len] {
371	            put32(&mut central, field);
372	        }
373	        for field in [name_len, 0, 0, 0, 0] {
374	            put16(&mut central, field);
375	        }
376	        put32(&mut central, EXTERNAL);
377	        put32(&mut central, offset);
378	        central.extend_from_slice(name.as_bytes());
379	    }
380	    let central_at = out.len() as u32;
381	    let central_len = central.len() as u32;
382	    out.extend_from_slice(&central);
383	    let count = entries.len() as u16;
384	    put32(&mut out, 0x0605_4b50);
385	    for field in [0, 0, count, count] {
386	        put16(&mut out, field);
387	    }
388	    put32(&mut out, central_len);
389	    put32(&mut out, central_at);
390	    put16(&mut out, 0);
391	    Ok(out)
392	}
393	
394	fn put16(out: &mut Vec<u8>, value: u16) {
395	    out.extend_from_slice(&value.to_le_bytes());
396	}
397	
398	fn put32(out: &mut Vec<u8>, value: u32) {
399	    out.extend_from_slice(&value.to_le_bytes());
400	}
